/* globals expect  */
import { transform } from '@babel/core'
import { Tag } from 'cerebral'
import plugin from 'babel-plugin-cerebral'

const pluginOptions = {
  babelrc: false,
  presets: ['@babel/preset-env'],
  plugins: [plugin],
}

const createFakeContext = (state) => ({
  controller: {
    getState(path) {
      return path.split('.').reduce((acc, curr) => {
        return acc[curr]
      }, state)
    },
  },
})

describe('Run transformed dot syntax', () => {
  it('should evaluate to a tag with nested tags', () => {
    const code = `
      import {state} from 'cerebral';
      state.a[state.b];
    `
    const state = {
      a: {
        c: 'Working!',
      },
      b: 'c',
    }
    const context = createFakeContext(state)
    const { code: result } = transform(code, pluginOptions)
    const tag = eval(result)
    expect(tag).toMatchSnapshot()
    expect(tag).toBeInstanceOf(Tag)
    expect(tag.getValue(context)).toEqual(state.a.c)
  })

  it('should allow to access with expressions in ${}', () => {
    const code = `
      import {state} from 'cerebral';
      const name = 'c';
      state.a[name][1+1];
    `

    const state = {
      a: {
        c: {
          2: 'Working!',
        },
      },
    }
    const context = createFakeContext(state)

    const { code: result } = transform(code, pluginOptions)
    const tag = eval(result)
    expect(tag).toBeInstanceOf(Tag)
    expect(tag.getValue(context)).toEqual(state.a.c[2])
  })

  it('should allow namespace imports', () => {
    const code = `
      import App, * as tags from 'cerebral';
      const name = 'c';
      tags.state.a[name][1+1];
    `

    const state = {
      a: {
        c: {
          2: 'Working!',
        },
      },
    }
    const context = createFakeContext(state)

    const { code: result } = transform(code, pluginOptions)
    const tag = eval(result)
    expect(tag).toBeInstanceOf(Tag)
    expect(tag.getValue(context)).toEqual(state.a.c[2])
  })
})
